import { newSpecPage } from '@stencil/core/testing';
import { ScPriceChoice } from '../sc-price-choice';

jest.mock('../../../../../services/fetch', () => ({
  getPricesAndProducts: jest.fn().mockResolvedValue({ prices: {}, products: {} }),
}));

describe('sc-price-choice', () => {
  it('renders', async () => {
    const page = await newSpecPage({
      components: [ScPriceChoice],
      html: `<sc-price-choice></sc-price-choice>`,
    });
    expect(page.root).toMatchSnapshot();
  });

  it('renders a price whose product was collapsed to an id (draft product)', async () => {
    const page = await newSpecPage({
      components: [ScPriceChoice],
      html: `<sc-price-choice></sc-price-choice>`,
    });
    // priceId first: its watcher fetches, then the store push below mirrors what the editor receives.
    page.root.priceId = 'price_1';
    await page.waitForChanges();
    page.root.products = {};
    page.root.prices = { price_1: { id: 'price_1', name: 'One-time', archived: false, product: 'prod_draft' } as any };
    await page.waitForChanges();

    expect(page.root.querySelector('sc-choice-container')).not.toBeNull();
    expect(page.root.querySelector('sc-alert')).toBeNull();
  });

  it('hides a price whose product is archived', async () => {
    const page = await newSpecPage({
      components: [ScPriceChoice],
      html: `<sc-price-choice></sc-price-choice>`,
    });
    page.root.priceId = 'price_1';
    await page.waitForChanges();
    page.root.products = { prod_1: { id: 'prod_1', archived: true } as any };
    page.root.prices = { price_1: { id: 'price_1', name: 'One-time', archived: false, product: 'prod_1' } as any };
    await page.waitForChanges();

    expect(page.root.querySelector('sc-choice-container')).toBeNull();
  });
});
